#include <stdio.h>
int main(void) {
    int n, a[21], x;
    if (scanf("%d", &n)!=1 || n<0 || n>20) return 1;
    for (int i=0; i<n; ++i) if (scanf("%d", &a[i])!=1) return 1;
    if (scanf("%d", &x)!=1) return 1;
    int lo=0, hi=n;
    while (lo<hi) {
        int m=lo+(hi-lo)/2;
        if (a[m]<x) lo=m+1; else hi=m;
    }
    for (int i=n; i>lo; --i) a[i]=a[i-1];
    a[lo]=x;
    for (int i=0; i<=n; ++i) printf("%s%d", i?" ":"", a[i]);
    printf("\n%d\n", lo);
    return 0;
}

